Here's a basic Node.js script you can use as a starting point:

```javascript
const http = require('http');

const server = http.createServer();
const port = process.env.PORT || 5900;

const publicPath = '/';

server.on('request', (req, res) => {
  console.log(`${req.method} ${req.headers['User-Agent']}`);
});

server.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
  process.stderr.write(JSON.stringify({ success: 'ok'}));
});
```

Run it from your CLI (`node index.js`) and watch the logs in the terminal. If you need real-time updates, use Node.js + WebSocket rather than sync.

